  r.push(naJ("1-12 PART C·E",["C 세력의 시나리오 — 만원에서 5만원까지","E 짧은 조정 — 판단의 위험"],"C는 조정이 오는 이유의 설명, E는 3일짜리 짧은 조정을 기간조정으로 오해하지 말라는 경고라 숫자 판정이 없습니다."));

  /* 1-13 */
  r.push(grp5("1-13 갭의 이해"));
  const gaps=[]; for(let i=n-120;i<n;i++){if(F.l[i]>F.h[i-1]*1.01) gaps.push({i,up:true,lo:F.h[i-1],hi:F.l[i]}); else if(F.h[i]<F.l[i-1]*0.99) gaps.push({i,up:false,lo:F.h[i],hi:F.l[i-1]});}
