    const box_=(()=>{const a=lastUp.i-60; return (F.h[hiIn(a,lastUp.i)]/F.l[loIn(a,lastUp.i)]-1)*100;})(), vb=F.v[lastUp.i]/avgV(lastUp.i-20,lastUp.i);
    const J4=[["긴 횡보 (60일 폭 25% 이하)",box_<=25],["폭발적 거래량 (3배↑)",vb>=3],["종가 유지 (갭 하방 위)",c>=lastUp.lo]];
