  const pl=pivots(F,4,n-60).lo; let twice=null; for(let a=pl.length-1;a>0&&!twice;a--) for(let b=a-1;b>=0;b--) if(Math.abs(F.l[pl[a]]/F.l[pl[b]]-1)<=0.02&&pl[a]-pl[b]>=5){twice=[pl[b],pl[a]];break;}
